// 1. Parent Class
class BaseMecha {
    constructor(name, hp, attackPower) {
        this.name = name;
        this.hp = hp;
        this.attackPower = attackPower;
    }
    attack(target) {
        return `BaseMecha '${this.name}' attacks ${target} for ${this.attackPower} damage!`;
    }
}

// 2. Child Class (Inheritance / Heritage)
class HeavyMecha extends BaseMecha {
    constructor(name, hp, attackPower, shieldPower) {
        super(name, hp, attackPower);
        this.shieldPower = shieldPower;
    }
    attack(target) {
        return `HeavyMecha '${this.name}' (HP:${this.hp}, Shield:${this.shieldPower}) attacks ${target} for ${this.attackPower} damage!`;
    }
}

// 3. Instantiate Hero Object
const hero = new HeavyMecha("Titan-X", 120, 85, 40);
